def count_words(text):
    words = text.split(' ')
    count = {}
    for word in words:
        if word in count:
            count[word] += 1
        else:
            count[word] = 0
    return count

def find_max(numbers):
    max_val = numbers[0]
    for i in range(len(numbers)):
        if numbers[i] > max_val:
            max_val = numbers[i]
    return max_val

import os

def delete_files(folder, extension):
    for f in os.listdir(folder):
        if f.endswith(extension):
            os.remove(f)
    print('Done')
